import React, { useState, useEffect } from "react"
import { AiOutlineLogout } from "react-icons/ai"
import { FaTimes } from "react-icons/fa"
import { useParams, useNavigate } from "react-router-dom"
import { googleLogout, GoogleOAuthProvider } from "@react-oauth/google"
import {
  userCreatedPinsQuery,
  userQuery,
  userSavedPinsQuery
} from "../utils/data"
import { client } from "../client"
import MasonryLayout from "./MasonryLayout"
import Spinner from "./Spinner"

const randomImage =
  "https://source.unsplash.com/1600x900/?nature,phototgraphy,technology"

const activeBtnStyles =
  "bg-red-500 text-white font-bold p-2 rounded-full w-20 outline-none"
const notActiveBtnStyles =
  "bg-primary-500 mr-4 text-black font-bold p-2 rounded-full w-20 outline-none"
const UserProfile = () => {
  const [user, setUser] = useState(null)
  const [pins, setPins] = useState(null)
  const [text, setText] = useState("Created")
  const [activeBtn, setActiveBtn] = useState("created")
  const navigate = useNavigate()
  const { sub } = useParams()

  const [showAlert, setShowAlert] = useState(false)
  // const handleLogout = async () => {
  //   try {
  //     googleLogout() // Call googleLogout to log out the user
  //     navigate("/", { replace: true }) // Navigate to the homepage
  //   } catch (error) {
  //     console.error("Logout failed", error)
  //   }
  // }
  const handleLogout = () => {
    console.log("logout handler")
    // localStorage.clear() or
    localStorage.removeItem("user")

    localStorage.setItem("showAlert", true)
    localStorage.setItem("username", user.userName)
    setShowAlert(true) // Set showAlert state to true to show the alert box
    navigate("/login", { replace: true })
  }
  useEffect(() => {
    const query = userQuery(sub)
    client.fetch(query).then((data) => {
      setUser(data[0])
    })
    setShowAlert(localStorage.getItem("showAlert") === "true")
    localStorage.removeItem("showAlert")
  }, [sub])

  useEffect(() => {
    if (text === "Created") {
      const createdPinsQuery = userCreatedPinsQuery(sub)

      client.fetch(createdPinsQuery).then((data) => {
        setPins(data)
      })
    } else {
      const savedPinsQuery = userSavedPinsQuery(sub)

      client.fetch(savedPinsQuery).then((data) => {
        setPins(data)
      })
    }
  }, [text, sub])

  if (!user) {
    return <Spinner message={"Loading Profile"} />
  }

  return (
    <div className="relative pb-2 h-full justify-center items-center">
      <div className="flex flex-col pb-5">
        <div className="relative flex flex-col mb-7 ">
          <div className="flex flex-col justify-center items-center">
            <img
              src={randomImage}
              className="w-full h-370 2xl:h-510 shadow-lg object-cover"
              alt="banner-pic"
            />
            <img
              className="rounded-full w-20 h-20 -mt-10 shadow-xl object-cover"
              src={user.image}
              alt="user-pic"
            />
            <h1 className="font-bold text-3xl text-center mt-3">
              {user.userName}
            </h1>
            <div className="absolute top-0 z-1 right-0 p-2">
              {sub === user._id && (
                <button
                  className="bg-white p-2 rounded-full cursor-pointer outline-none shadow-md opacity-70 hover:opacity-100"
                  onClick={handleLogout}
                >
                  <AiOutlineLogout fontSize={21} color="red" />
                </button>
              )}
            </div>
          </div>
          <div className="text-center mb-7">
            <button
              type="button"
              onClick={(e) => {
                setText(e.target.textContent)
                setActiveBtn("created")
              }}
              className={`${
                activeBtn === "created" ? activeBtnStyles : notActiveBtnStyles
              }`}
            >
              Created
            </button>
            <button
              type="button"
              onClick={(e) => {
                setText(e.target.textContent)
                setActiveBtn("saved")
              }}
              className={`${
                activeBtn === "saved" ? activeBtnStyles : notActiveBtnStyles
              }`}
            >
              Saved
            </button>
          </div>
          {pins?.length ? (
            <div className="px-2">
              <MasonryLayout pins={pins} />
            </div>
          ) : (
            <div className="flex-justify-center font-bold items-center w-full text-xl mt-2">
              No Pins Found!
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

export default UserProfile
